const roles = [
  'Data Analyst',
  'Senior Data Analyst',
  'Data Engineer',
  'BI Developer'
];

const resumeText = $input.first().json.resumeText;
const searchDate = $input.first().json.searchDate;

const items = roles.map(role => {
  const encodedRole = encodeURIComponent(role);
  // LinkedIn job search URL:
  // f_TPR=r86400 => past 24 hours
  // location=United States
  // f_WT=2 => remote
  // sortBy=DD => most recent
  const linkedInUrl = `https://www.linkedin.com/jobs/search/?keywords=${encodedRole}&location=United%20States&f_TPR=r86400&f_WT=2&sortBy=DD`;
  return {
    json: {
      role: role,
      searchUrl: linkedInUrl,
      resumeText: resumeText,
      searchDate: searchDate
    }
  };
});

return items;

const html = $input.item.json.data || $input.item.json.body || '';
const role = $input.item.json.role || 'Unknown Role';
const resumeText = $input.item.json.resumeText || '';
const searchDate = $input.item.json.searchDate || '';

const jobs = [];

// Parse LinkedIn public job search results page
// LinkedIn public search returns job cards with data in specific patterns

// Pattern 1: Extract from job card links (public search page)
const jobCardRegex = /href="(https:\/\/www\.linkedin\.com\/jobs\/view\/[^"?]+)/g;
let match;
const seenUrls = new Set();

while ((match = jobCardRegex.exec(html)) !== null) {
  const jobUrl = match[1];
  if (!seenUrls.has(jobUrl)) {
    seenUrls.add(jobUrl);
    jobs.push({ jobUrl });
  }
}

// Pattern 2: Extract from JSON-LD structured data if present
const jsonLdRegex = /"@type"\s*:\s*"JobPosting"[^}]*"title"\s*:\s*"([^"]+)"[^}]*"hiringOrganization"\s*:\s*\{[^}]*"name"\s*:\s*"([^"]+)"[^}]*"url"\s*:\s*"([^"]+)"/g;
while ((match = jsonLdRegex.exec(html)) !== null) {
  const jobUrl = match[3];
  if (!seenUrls.has(jobUrl)) {
    seenUrls.add(jobUrl);
    jobs.push({
      jobTitle: match[1],
      companyName: match[2],
      jobUrl: jobUrl
    });
  }
}

// Pattern 3: Extract from base-card pattern (guest/public view)
const baseCardRegex = /base-card[^>]*>.*?<a[^>]*href="(https:\/\/www\.linkedin\.com\/jobs\/view\/[^"?]+)"[^>]*>.*?<span[^>]*>\s*([^<]+?)\s*<\/span>.*?<h4[^>]*>.*?<a[^>]*>\s*([^<]+?)\s*<\/a>/gs;
while ((match = baseCardRegex.exec(html)) !== null) {
  const jobUrl = match[1];
  if (!seenUrls.has(jobUrl)) {
    seenUrls.add(jobUrl);
    jobs.push({
      jobTitle: match[2].trim(),
      companyName: match[3].trim(),
      jobUrl: jobUrl
    });
  }
}

// If no jobs found, return a placeholder so the workflow continues
if (jobs.length === 0) {
  return [{
    json: {
      role: role,
      resumeText: resumeText,
      searchDate: searchDate,
      jobUrl: '',
      jobTitle: '',
      companyName: '',
      noJobsFound: true
    }
  }];
}

// Limit to top 10 per role to stay within free tier limits
return jobs.slice(0, 10).map(job => ({
  json: {
    role: role,
    resumeText: resumeText,
    searchDate: searchDate,
    jobUrl: job.jobUrl,
    jobTitle: job.jobTitle || '',
    companyName: job.companyName || '',
    noJobsFound: false
  }
}));

const html = $input.item.json.data || $input.item.json.body || '';
let jobTitle = $input.item.json.jobTitle || '';
let companyName = $input.item.json.companyName || '';
let jobDescription = '';
let datePosted = '';

// Extract job title from page if not already set
if (!jobTitle) {
  // Try <title> tag
  const titleMatch = html.match(/<title[^>]*>([^<|]+)/i);
  if (titleMatch) {
    jobTitle = titleMatch[1].trim();
  }
  // Try h1 with specific class
  const h1Match = html.match(/<h1[^>]*class="[^"]*top-card-layout__title[^"]*"[^>]*>\s*([^<]+)/i);
  if (h1Match) {
    jobTitle = h1Match[1].trim();
  }
}

// Extract company name from page if not already set
if (!companyName) {
  const companyMatch = html.match(/<a[^>]*class="[^"]*topcard__org-name-link[^"]*"[^>]*>\s*([^<]+)/i)
    || html.match(/"hiringOrganization"\s*:\s*\{[^}]*"name"\s*:\s*"([^"]+)"/i)
    || html.match(/<span[^>]*class="[^"]*company-name[^"]*"[^>]*>\s*([^<]+)/i);
  if (companyMatch) {
    companyName = companyMatch[1].trim();
  }
}

// Extract date posted
const dateMatch = html.match(/"datePosted"\s*:\s*"([^"]+)"/i)
  || html.match(/<span[^>]*class="[^"]*posted-time-ago[^"]*"[^>]*>\s*([^<]+)/i)
  || html.match(/<time[^>]*datetime="([^"]+)"/i);
if (dateMatch) {
  datePosted = dateMatch[1].trim();
}

// Extract job description
// Try JSON-LD first
const jsonLdDescMatch = html.match(/"description"\s*:\s*"((?:[^"\\]|\\.)*)"/i);
if (jsonLdDescMatch) {
  jobDescription = jsonLdDescMatch[1]
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, ' ')
    .replace(/\\u003c/g, '<')
    .replace(/\\u003e/g, '>')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Try description section div
if (!jobDescription) {
  const descMatch = html.match(/<div[^>]*class="[^"]*description__text[^"]*"[^>]*>([\s\S]*?)<\/div>/i)
    || html.match(/<div[^>]*class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i)
    || html.match(/<section[^>]*class="[^"]*description[^"]*"[^>]*>([\s\S]*?)<\/section>/i);
  if (descMatch) {
    jobDescription = descMatch[1]
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#\d+;/g, '')
      .replace(/\s+/g, ' ')
      .trim();
  }
}

// Truncate description to stay within API limits (keep first 4000 chars)
if (jobDescription.length > 4000) {
  jobDescription = jobDescription.substring(0, 4000) + '...';
}

return [{
  json: {
    role: $input.item.json.role,
    resumeText: $input.item.json.resumeText,
    searchDate: $input.item.json.searchDate,
    jobUrl: $input.item.json.jobUrl,
    jobTitle: jobTitle || $input.item.json.role,
    companyName: companyName || 'Unknown Company',
    datePosted: datePosted || $input.item.json.searchDate,
    jobDescription: jobDescription || 'Job description could not be extracted. Please visit the job URL for details.'
  }
}];

